{"content": "/**
 * JSON depth validation
 * Validates that JSON nesting depth does not exceed maximum allowed level
 */

import { ValidationError, VALIDATION_ERROR_TYPES } from '../types/validation-errors.js';

/**
 * Recursively validate JSON depth
 * Counts the maximum nesting level of objects and arrays
 * @param obj The object to validate
 * @param currentDepth Current depth level
 * @param maxDepth Maximum allowed depth
 * @throws ValidationError if depth exceeds maximum
 */
function validateDepthRecursive(obj: unknown, currentDepth: number, maxDepth: number): void {
  // If we've gone deeper than maxDepth, throw error
  if (currentDepth > maxDepth) {
    throw new ValidationError(
      VALIDATION_ERROR_TYPES.JSON_DEPTH_EXCEEDED,
      `JSON nesting depth exceeds maximum of ${maxDepth} levels`
    );
  }

  // Recurse into objects
  if (typeof obj === 'object' && obj !== null) {
    if (Array.isArray(obj)) {
      // For arrays, traverse each element
      for (const item of obj) {
        validateDepthRecursive(item, currentDepth + 1, maxDepth);
      }
    } else {
      // For objects, traverse each property value
      for (const key in obj) {
        if (Object.prototype.hasOwnProperty.call(obj, key)) {
          const value = (obj as Record<string, unknown>)[key];
          validateDepthRecursive(value, currentDepth + 1, maxDepth);
        }
      }
    }
  }
  // Primitive values don't increase depth, just return
}

/**
 * Validate JSON nesting depth
 * Throws ValidationError if nesting depth exceeds maximum
 * @param obj The parsed JSON object to validate
 * @param maxDepth The maximum allowed nesting depth
 * @throws ValidationError if depth exceeds limit
 */
export function validateJsonDepth(obj: unknown, maxDepth: number): void {
  // Start validation at depth 1 (the root object/array itself)
  validateDepthRecursive(obj, 1, maxDepth);
}
